                    "sql": "create or replace table maplemonk.beastlife_shiprocket_Query as WITH p AS ( SELECT * FROM maplemonk.Beastlife_db_Shiprocket_pickedup_ WHERE TRUE QUALIFY ROW_NUMBER() OVER ( PARTITION BY awb ORDER BY picked_up_date IS NULL, picked_up_date ) = 1 ), u AS ( SELECT * FROM `maplemonk.beastlife_unicommerce_fact_items` WHERE reference_code IS NOT NULL QUALIFY ROW_NUMBER() OVER ( PARTITION BY reference_code ORDER BY (shippingPackageStatus = \'CANCELLED\'), shippingPackageStatus ) = 1 ), d AS ( SELECT * FROM `maplemonk.D2C_master` WHERE TRUE QUALIFY ROW_NUMBER() OVER ( PARTITION BY ordeR_name ORDER BY Order_Date, order_time ) = 1 ), calendar AS ( SELECT PARSE_DATE(\'%Y-%m-%d\', event_date) AS event_date, Event, sub_event, FORMAT_DATE(\'%Y%m%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateAsInteger, FORMAT_DATE(\'%d\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DateNumber, EXTRACT(YEAR FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS Year, FORMAT_DATE(\'%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNumber, FORMAT_DATE(\'%Y/%m\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthNumber, FORMAT_DATE(\'%Y/%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS YearMonthShort, FORMAT_DATE(\'%b\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameShort, FORMAT_DATE(\'%B\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS MonthNameLong, EXTRACT(DAYOFWEEK FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekNumber, FORMAT_DATE(\'%A\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeek, FORMAT_DATE(\'%a\', PARSE_DATE(\'%Y-%m-%d\', event_date)) AS DayOfWeekShort, CONCAT(\'Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING)) AS Quarter, CONCAT(FORMAT_DATE(\'%Y\', PARSE_DATE(\'%Y-%m-%d\', event_date)),\'/Q\', CAST(EXTRACT(QUARTER FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) AS STRING)) AS YearQuarter, CASE WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 1 AND 7 THEN \'W1\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 8 AND 14 THEN \'W2\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 15 AND 21 THEN \'W3\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) BETWEEN 22 AND 28 THEN \'W4\' WHEN EXTRACT(DAY FROM PARSE_DATE(\'%Y-%m-%d\', event_date)) >= 29 THEN \'W5\' END AS WeekPeriod FROM `beastlife-wh-474411.maplemonk.beastlife_db_Calender` ), catalog AS ( SELECT Category, SKU_Code, SKU_Type, Ingredients, Rev_Category, Sub_Category, Category_Type, Product_Name__as_on_Product_Packaging_, MAX(Flavour) AS Flavour, SUM(CAST(MRP AS NUMERIC)) AS MRP, SUM(CAST(MRP_Revised AS NUMERIC)) AS MRP_Revised,sku_details_Size FROM `beastlife-wh-474411.maplemonk.MasterCatalogue` GROUP BY 1,2,3,4,5,6,7,8,12 ) SELECT calendar.*, f.channel_order_id,f.awb,f.courier,zone,d.Order_Date,EXTRACT(HOUR FROM d.order_time) AS hour,f.order_status, DATE(SAFE.PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\',COALESCE(NULLIF(f.picked_up_date, \'\'), p.picked_up_date),\'Asia/Kolkata\' )) AS picked_up_date, awb_assign_date, f.delivered_date, pickup_scheduled_date,pickup_location,f.payment_method, rto_delivered_date, rto_initiated_date, EXTRACT(HOUR FROM SAFE.PARSE_TIMESTAMP( \'%Y-%m-%d %H:%M:%S\', COALESCE(NULLIF(f.picked_up_date, \'\'), p.picked_up_date), \'Asia/Kolkata\' ) ) AS PickedUp_hour, CASE WHEN UPPER(f.order_status) LIKE \'%RTO%\' THEN NULL ELSE DATE_DIFF( COALESCE(DATE(f.delivered_date), CURRENT_DATE(\'Asia/Kolkata\')), DATE(SAFE.PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', COALESCE(NULLIF(f.picked_up_date, \'\'), p.picked_up_date), \'Asia/Kolkata\')), DAY ) END AS TAT_Days, CASE WHEN UPPER(f.order_status) LIKE \'%RTO%\' THEN NULL WHEN f.delivered_date IS NOT NULL THEN CASE WHEN DATE_DIFF( DATE(f.delivered_date), DATE(SAFE.PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', COALESCE(NULLIF(f.picked_up_date, \'\'), p.picked_up_date), \'Asia/Kolkata\')), DAY ) > CASE WHEN zone = \'z_a\' AND UPPER(f.courier) LIKE \'%NDD%\' THEN 1 WHEN zone = \'z_b\' AND UPPER(f.courier) LIKE \'%NDD%\' THEN 1 WHEN zone = \'z_a\' AND UPPER(f.courier) LIKE \'%SURFACE%\' THEN 2 WHEN zone = \'z_a\' THEN 1 WHEN zone = \'z_b\' THEN 3 WHEN zone = \'z_c\' THEN 5 WHEN zone = \'z_d\' THEN 7 WHEN zone = \'z_e\' THEN 9 ELSE NULL END THEN \'TAT Breached\' ELSE \'Not Breached\' END ELSE CASE WHEN DATE_DIFF( CURRENT_DATE(\'Asia/Kolkata\'), DATE(SAFE.PARSE_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', COALESCE(NULLIF(f.picked_up_date, \'\'), p.picked_up_date), \'Asia/Kolkata\')), DAY ) > CASE WHEN zone = \'z_a\' AND UPPER(f.courier) LIKE \'%NDD%\' THEN 1 WHEN zone = \'z_b\' AND UPPER(f.courier) LIKE \'%NDD%\' THEN 1 WHEN zone = \'z_a\' AND UPPER(f.courier) LIKE \'%SURFACE%\' THEN 2 WHEN zone = \'z_a\' THEN 1 WHEN zone = \'z_b\' THEN 3 WHEN zone = \'z_c\' THEN 5 WHEN zone = \'z_d\' THEN 7 WHEN zone = \'z_e\' THEN 9 ELSE NULL END THEN \'TAT Breached\' ELSE \'Not Breached\' END END AS TAT_Breach_Status, CASE COALESCE(shippingPackageStatus, u.ORDER_STATUS) WHEN \'DELIVERED\' THEN \'DISPATCHED\' WHEN \'RETURN_EXPECTED\' THEN \'DISPATCHED\' WHEN \'SHIPPED\' THEN \'DISPATCHED\' WHEN \'RETURN_ACKNOWLEDGED\' THEN \'DISPATCHED\' WHEN \'MANIFESTED\' THEN \'DISPATCHED\' WHEN \'DISPATCHED\' THEN \'DISPATCHED\' WHEN \'RETURNED\' THEN \'RETURNED\' WHEN \'CANCELLED\' THEN \'CANCELLED\' WHEN \'ALTERNATE_ACCEPTED\' THEN \'ALTERNATE_ACCEPTED\' WHEN \'PACKED\' THEN \'PACKED\' WHEN \'READY_TO_SHIP\' THEN \'READY_TO_SHIP\' WHEN \'PICKED\' THEN \'PICKED\' WHEN \'PICKING\' THEN \'PICKING\' WHEN \'CREATED\' THEN \'CREATED\' WHEN \'FULFILLABLE\' THEN \'UNFULFILLABLE\' WHEN \'UNFULFILLABLE\' THEN \'UNFULFILLABLE\' ELSE \'UNKNOWN\' END AS Consolidated_Status FROM `maplemonk.beastlife_shiprocket_fact_items_current` f LEFT JOIN p ON f.awb = p.awb LEFT JOIN u ON f.channel_order_id = u.reference_code LEFT JOIN d ON f.channel_order_id = d.ordeR_name LEFT JOIN calendar ON DATE(SAFE_CAST(NULLIF(TRIM(f.picked_up_date), \'\') AS TIMESTAMP)) = calendar.event_date",
